// Interfaz del C-Gear. Los datos viven en docs/datos/*.json; los cálculos, en calculos.js.
import {TN,TT,ESPECIES,CAPS,xf,mult,mejorGolpe,celda,golpeRecibido,temporada} from './calculos.js';
import {contar,barra,destellar,celebrar,evolucionar,reducido} from './efectos.js';

const MEDALLAS=[['Trío','Zeo','#7fd38a'],['Básica','Aloe','#d8d3c4'],['Élitro','Camus','#b5c43f'],['Voltio','Camila','#f2d03f'],['Temblor','Yakón','#d9a766'],['Jet','Gerania','#a6b4ee'],['Glaciar','Junco','#8fdde0'],['Leyenda','Iris','#6f8cf0']];
const PRUEBAS={t:'tu partida',p:'wiki de PokeMMO',b:'juego original',c:'texto del juego',a:'consejo'};
const IC={ahora:'M12 3l8 5v8l-8 5-8-5V8z',ruta:'M5 21V8a3 3 0 016 0v8a3 3 0 006 0V4M15 7l2-3 2 3',combate:'M4 4l8 8M4 4h4M4 4v4M20 4l-8 8M20 4h-4M20 4v4M7 15l-3 5M17 15l3 5',dinero:'M12 3a9 9 0 100 18 9 9 0 000-18zM12 7v10M9 15c1 1 5 1 6-1s-6-3-5-5 4-1 5 0',regiones:'M3 6l6-2 6 2 6-2v14l-6 2-6-2-6 2zM9 4v14M15 6v14',mas:'M4 7h16M4 12h16M4 17h16',objetos:'M4 8l8-4 8 4v9l-8 4-8-4zM4 8l8 4 8-4M12 12v9',personaje:'M12 12a4 4 0 100-8 4 4 0 000 8zM4 21c1-5 5-7 8-7s7 2 8 7'};
const VISTAS=[['ahora','Ahora'],['ruta','Ruta'],['combate','Combate'],['objetos','Objetos'],['dinero','Dinero'],['personaje','Personaje'],['mas','Más']];
const OTRAS=['regiones'];
const CLAVE='cgear-tato';
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const spr=id=>'img/sprites/'+id+'.png';
const ani=(id,cl='spr')=>'<img class="'+cl+'" alt="" loading="lazy" src="img/animados/'+id+'.gif" onerror="this.onerror=null;this.src=\'img/sprites/'+id+'.png\'">';
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const EV_MAX={gat:30,fla:20,inc:8};
const previo={};
let E,RUTA,RIV,INM,DIN,OBJ,PER,COS,objSec='equipo',perSec='ficha',objFiltro='todo',cosG='Sombreros',cosQ='',dinSec='resumen',soloYa=false,rivalSel=null,tiposSel=[],boost=1,msg='',modoCombate='versus',filtro='todo',q='',mapaDibujado=false,instalar=null,saltar=null;

/* ---------- Datos y guardado ---------- */
async function json(n){const r=await fetch('datos/'+n+'.json');if(!r.ok)throw new Error(n);return r.json()}
function leerLocal(){try{const r=localStorage.getItem(CLAVE);return r?JSON.parse(r):null}catch(e){return null}}
// Gana la copia más reciente. Lo marcado en cualquiera de las dos se conserva.
function fusiona(base,local){if(!local||!Array.isArray(local.equipo))return base;const nueva=(local.actualizado||'')>=(base.actualizado||'')?local:base,vieja=nueva===local?base:local;
 const timers=Object.assign({},vieja.timers,nueva.timers);for(const k of Object.keys(vieja.timers||{}))timers[k]=Math.max(vieja.timers[k]||0,timers[k]||0);
 return Object.assign({},nueva,{hechos:Object.assign({},vieja.hechos,nueva.hechos),timers})}
function guardar(){E.actualizado=new Date().toISOString();try{localStorage.setItem(CLAVE,JSON.stringify(E))}catch(e){}}

/* ---------- Ayudas ---------- */
const lim=()=>CAPS.Teselia[Math.min(E.medallas,8)];
const sigLim=()=>E.medallas>=8?100:CAPS.Teselia[E.medallas+1];
const tipoH=t=>'<span class="tipo" style="--c:var(--t-'+t+')">'+TN[t]+'</span>';
const pruebaH=p=>'<span class="prueba '+p+'">'+PRUEBAS[p]+'</span>';
const obligatorios=f=>f.lugares.flatMap(l=>l.pasos).filter(p=>!p[4]);
const faseSuperada=f=>f.med<=E.medallas;
const pasoHecho=(p,f)=>!!E.hechos[p[0]]||(!p[4]&&faseSuperada(f));
const progreso=()=>{const t=RUTA.fases.filter(f=>f.med<10).flatMap(f=>obligatorios(f).map(p=>pasoHecho(p,f)));return t.filter(Boolean).length/t.length};
const pendientes=()=>RUTA.fases.flatMap(f=>f.med<10?obligatorios(f).filter(p=>!pasoHecho(p,f)):[]);
function rivalSiguiente(){return E.medallas>=8?'anis':E.medallas>=7?'iris':E.medallas>=6?'junco':E.medallas>=5&&E.hechos.n4?'gerania':E.medallas===5?'n4':RIV.find(r=>r.med===E.medallas).id}
function cuentaEvento(){const ms=Date.UTC(2026,10,13,23,59)-Date.now();return ms<=0?null:Math.floor(ms/864e5)+' d '+Math.floor(ms%864e5/36e5)+' h'}
function avisos(m){const a=[],e=ESPECIES[m.sp];
 if(e.cond&&e.cond.startsWith('Nv.')&&m.nv>=+e.cond.slice(3))a.push(['Le toca evolucionar a '+e.evo+' ('+e.cond+').','']);
 if(m.sp==='Graveler')a.push(['Agua y Planta le hacen ×4. Evoluciona a Golem solo por intercambio, con alguien de confianza que te lo devuelva.','mal']);
 if(/^(Dratini|Dragonair|Dragonite)$/.test(m.sp)&&/miedosa/.test(m.nat))a.push(['Su naturaleza baja Ataque y sus tres ataques son físicos. Rendirá mejor con ataques especiales.','mal']);
 if(m.sp==='Serperior'&&m.mov.some(x=>x[0]==='Corte'))a.push(['Corte es su hueco más flojo. Si no lo necesitas para el mapa, cámbialo.','']);
 if(m.nv>=lim())a.push(['Está en el límite de obediencia (Nv.'+lim()+'). La experiencia extra se guarda hasta la próxima medalla.','']);
 return a}

/* ---------- Piezas ---------- */
function monH(m,i){const e=ESPECIES[m.sp];return '<article class="mon"><div class="mon-top">'+ani(e.id)+'<div><h3>'+esc(m.sp)+'</h3><div class="nv"><button class="mini" data-nv="'+i+':-1" aria-label="Bajar nivel de '+esc(m.sp)+'">−</button>Nv.'+m.nv+'<button class="mini" data-nv="'+i+':1" aria-label="Subir nivel de '+esc(m.sp)+'">+</button></div></div></div><div class="tipos">'+e.t.map(tipoH).join('')+'</div><ul class="movs">'+m.mov.map((v,j)=>'<li><button data-mov="'+i+':'+j+'"><span>'+esc(v[0])+'</span>'+tipoH(v[1])+'</button></li>').join('')+'</ul><p class="nota">Naturaleza '+esc(m.nat)+'</p>'+avisos(m).map(a=>'<p class="aviso '+a[1]+'">'+esc(a[0])+'</p>').join('')+(e.evo?'<div class="fila-acc"><button class="mini" data-evo="'+i+'">Ya es '+esc(e.evo)+'</button></div>':'')+'</article>'}
function pasoH(p,f){const on=pasoHecho(p,f),auto=on&&!E.hechos[p[0]];return '<li class="paso'+(on?' hecho':'')+'"><input type="checkbox" id="p-'+p[0]+'" data-paso="'+p[0]+'"'+(on?' checked':'')+(auto?' disabled':'')+' aria-label="'+esc(p[1])+'"><div><label for="p-'+p[0]+'"><b class="t">'+esc(p[1])+(p[4]?'<span class="prueba opc">opcional</span>':'')+pruebaH(p[3])+'</b></label><p>'+esc(p[2])+'</p></div></li>'}
function matriz(rv){const eq=E.equipo;let h='<div class="tablazo" tabindex="0" role="region" aria-label="Matriz contra '+esc(rv.nom)+'"><table class="matriz"><thead><tr><th>Rival</th>'+eq.map(m=>'<th><img class="spr" alt="" src="'+spr(ESPECIES[m.sp].id)+'">'+esc(m.sp)+'</th>').join('')+'</tr></thead><tbody>';
 for(const r of rv.eq){const fila=eq.map(m=>celda(m,r,INM)),top=fila.reduce((a,b,i)=>b.s>fila[a].s?i:a,0);
  h+='<tr><th><div class="rival"><img class="spr" alt="" src="'+spr(r[1])+'"><div>'+esc(r[0])+' Nv.'+r[2]+'<small>'+esc(r[5]||r[3].map(t=>TN[t]).join(' / '))+'</small></div></div></th>';
  fila.forEach((c,i)=>{const cl=(c.g.m>=2&&c.d.m<2)?'bien':(c.d.m>=2&&c.g.m<2)?'mal':'';h+='<td class="celda '+cl+(i===top?' top':'')+'"><b>'+esc(c.g.n)+' '+xf(c.g.m)+'</b><span class="'+(c.d.m>=4?'x4':'')+'">Recibe '+esc(c.d.n)+' '+xf(c.d.m)+'</span></td>'});h+='</tr>'}
 return h+'</tbody></table></div><div class="leyenda"><span><i style="background:#1d4a39"></i>Pegas fuerte y aguantas</span><span><i style="background:#5a2a2a"></i>Te pega más de lo que pegas</span><span><i style="outline:2px solid var(--oro);outline-offset:-2px"></i>Mejor opción para esa fila</span></div><p class="nota">Solo cuenta tipos, potencia y misma-tipo. No ve niveles, estadísticas ni objetos: te orienta y la decisión es tuya.</p>'}
function versus(rv){return '<div class="versus">'+rv.eq.map((r,ri)=>{const f=E.equipo.map(m=>({m,c:celda(m,r,INM)})).sort((a,b)=>b.c.s-a.c.s),max=Math.max(f[0].c.s,1);
  return '<article class="vs"><header>'+ani(r[1])+'<div><h3>'+esc(r[0])+' <span class="nota">Nv.'+r[2]+'</span></h3><div class="tipos">'+r[3].map(tipoH).join('')+'</div>'+(r[5]?'<p class="nota">'+esc(r[5])+'</p>':'')+'</div></header><ol class="rank">'+f.map((x,i)=>{const d=x.c.d,g=x.c.g,cl=d.m>=4?'peligro':g.m>=2&&d.m<2?'bien':d.m>=2&&g.m<2?'mal':'';return '<li class="'+cl+'" style="--i:'+(ri*2+i)+'"><img class="spr" alt="" src="'+spr(ESPECIES[x.m.sp].id)+'"><div class="rank-t"><b>'+esc(x.m.sp)+(i===0?'<span class="prueba elige">mejor</span>':'')+'</b><span>'+esc(g.n)+' '+xf(g.m)+' · recibe '+esc(d.n)+' '+xf(d.m)+'</span><span class="bv"><i style="transform:scaleX('+(x.c.s/max).toFixed(3)+')"></i></span></div></li>'}).join('')+'</ol></article>'}).join('')+'</div><p class="nota">Solo cuenta tipos, potencia y misma-tipo. No ve niveles, estadísticas ni objetos: te orienta y la decisión es tuya.</p>'}
function indice(){const out=[];RUTA.fases.forEach(f=>f.lugares.forEach((l,i)=>{const ir=f.id+':'+i,add=(tp,x)=>out.push({tp,x,ir,donde:l.es,fase:f.nom,n:norm(x+' '+l.en)});add('Lugar',l.es+' · '+l.en);l.pasos.forEach(p=>add('Paso',p[1]+': '+p[2]));(l.objetos||[]).forEach(o=>add('Objeto',o));if(l.salvajes)add('Salvajes',l.salvajes)}));OBJ.equipables.forEach(o=>out.push({tp:'Objeto',x:o.es+' ('+o.en+'): '+o.efecto+'. '+o.donde,obj:'equipables',donde:'Objetos',fase:'Objetos',n:norm(o.es+' '+o.en+' '+o.efecto+' '+o.para+' '+o.donde)}));OBJ.para_mi.forEach(o=>out.push({tp:'Objeto',x:o.es+': '+o.donde,obj:'mios',donde:'Objetos para ti',fase:'Objetos',n:norm(o.es+' '+o.para+' '+o.donde)}));OBJ.mt.forEach(o=>out.push({tp:'MT',x:o.es+': '+o.donde,obj:'mt',donde:'MT',fase:'Objetos',n:norm('mt '+o.es+' '+o.donde)}));Object.entries(COS).forEach(([g,v])=>v.forEach(x=>out.push({tp:'Cosmético',x,per:1,donde:g,fase:'Personaje',n:norm(x+' '+g)})));DIN.metodos.forEach(m=>out.push({tp:'Dinero',x:m.nom+': '+m.frase,din:m.id,donde:'Guía del dinero',fase:'Dinero',n:norm(m.nom+' '+m.frase+' '+m.pasos.join(' ')+' '+m.necesitas.join(' '))}));RIV.forEach(r=>r.eq.forEach(m=>out.push({tp:'Rival',x:m[0]+' Nv.'+m[2]+' de '+r.nom,riv:r.id,donde:r.lugar,fase:'Combate',n:norm(m[0]+' '+r.nom)})));return out}
function resultados(){const w=norm(q).trim().split(/\s+/).filter(Boolean);if(!w.length)return'';const r=indice().filter(o=>w.every(k=>o.n.includes(k))).slice(0,40);if(!r.length)return'<p class="nota">Nada con esa búsqueda. Prueba con menos palabras o con el nombre en inglés.</p>';return '<p class="nota">'+r.length+(r.length===40?' primeros resultados':r.length===1?' resultado':' resultados')+'</p><ul class="hallazgos">'+r.map(o=>'<li><button '+(o.per?'data-ir-per="1"':o.obj?'data-ir-obj="'+o.obj+'"':o.din?'data-ir-din="'+o.din+'"':o.riv?'data-ir-riv="'+o.riv+'"':'data-ir="'+o.ir+'"')+'><span class="prueba p">'+o.tp+'</span><b>'+esc(o.donde)+'</b><span>'+esc(o.x)+'</span></button></li>').join('')+'</ul>'}
function pasosFiltrados(l,f){return l.pasos.filter(p=>filtro==='todo'||(filtro==='pend'&&!p[4]&&!pasoHecho(p,f))||(filtro==='opc'&&p[4]&&!pasoHecho(p,f)))}
function planDe(r){const tops={},al=[];for(const x of r.eq){let bi=0,bs=-1;E.equipo.forEach((m,i)=>{const s=celda(m,x,INM).s;if(s>bs){bs=s;bi=i}});const m=E.equipo[bi];(tops[m.sp]=tops[m.sp]||[]).push(x[0]+' con '+mejorGolpe(m,x,INM).n);E.equipo.forEach(m2=>{const d=golpeRecibido(x,m2);if(d.m>=4)al.push(m2.sp+' recibe ×'+d.m+' de '+x[0]+' ('+d.n+')')})}
 const pp=Object.values(tops).flat().some(x=>x.includes('Hidrobomba'));
 return '<ul class="lista">'+Object.entries(tops).map(([k,v])=>'<li><b>'+esc(k)+':</b> '+esc(v.join('; '))+'.</li>').join('')+al.map(a=>'<li class="aviso mal suelto">Cuidado: '+esc(a)+'.</li>').join('')+(pp?'<li class="aviso suelto">Hidrobomba solo tiene 5 PP y puede fallar. Surf es la opción segura.</li>':'')+'</ul>'}
function tablaTipos(){if(!tiposSel.length)return'<p class="nota">Aún no hay tipos elegidos.</p>';const g={};for(const t of TT){const m=mult(t,tiposSel);(g[m]=g[m]||[]).push(t)}return[4,2,.5,.25,0].filter(k=>g[k]).map(k=>'<div><b>'+xf(k)+'</b><div class="tipos">'+g[k].map(tipoH).join('')+'</div></div>').join('')}
const TIM=()=>[...new Set(['Teselia',...ligasReales()])].flatMap(r=>[['liga-'+r,'Liga de '+r,E.ligaH||18],['gyms-'+r,'Gimnasios de '+r,18],['rev-'+r,'Entrenadores de '+r,6]]).concat([['bayas','Bayas (regar y cosechar)',20]]);
function timersH(){return TIM().map(([id,n,h])=>{const ms=(E.timers[id]||0)+h*36e5-Date.now(),ok=ms<=0,f=ok?'Listo':[ms/36e5,ms%36e5/6e4,ms%6e4/1e3].map(v=>String(Math.floor(v)).padStart(2,'0')).join(':');return '<div class="timer'+(ok?' listo':'')+'"><h3>'+n+'</h3><b>'+f+'</b><span class="bv"><i style="transform:scaleX('+(ok?1:(1-ms/(h*36e5))).toFixed(4)+')"></i></span><span class="nota">Espera de '+h+' h</span><button class="btn sec" data-timer="'+id+'">Hecho ahora</button></div>'}).join('')}
function mapa(){const N=[['f1','P. Arcilla',620,375,1],['f1','Terracota',612,300,1],['f1','Gres',607,235,1],['f2','Esmalte',490,232,2],['f3','Porcelana',408,332,3],['f4','Mayólica',405,225,4],['f5','Fayenza',288,232,5],['f6','Electrorroca',248,198,6],['f6','Loza',205,150,6],['f7','Teja',255,84,7],['f8','Caolín',450,84,8],['f9','Liga',405,36,9]];
 const pts=N.map(n=>n[2]+','+n[3]),ix=N.findIndex(x=>x[4]>E.medallas);let aqui=ix<0?N.length-1:ix;if(E.medallas===5&&E.hechos.torre)aqui=8;
 return '<section class="mapa" aria-label="Mapa esquemático de la ruta por Teselia"><svg viewBox="70 0 610 410" role="img"><polyline class="ruta" points="'+pts.join(' ')+'"/><polyline class="ruta2'+(mapaDibujado||reducido()?'':' dibuja')+'" pathLength="1" points="'+pts.slice(0,aqui+1).join(' ')+'"/>'+N.map((x,i)=>{const cl=i<aqui?'hecho':i===aqui?'aqui':'',inf=[0,4,6].includes(i),izq=[1,5,7,8].includes(i);return '<g class="nodo '+cl+'" data-fase="'+x[0]+'"><circle cx="'+x[2]+'" cy="'+x[3]+'" r="'+(i===aqui?11:8)+'"/><text x="'+(x[2]+(izq?-18:0))+'" y="'+(x[3]+(izq?6:inf?32:-16))+'" text-anchor="'+(izq?'end':'middle')+'">'+x[1]+'</text></g>'}).join('')+'</svg></section>'}
function lugarH(l,f,abierto,i){const pe=l.pasos.filter(p=>!pasoHecho(p,f)).length;return '<details class="lugar" id="'+f.id+'-'+i+'"'+(abierto?' open':'')+'><summary><span>'+esc(l.es)+'<small>'+esc(l.en)+'</small></span><small>'+(pe?pe+' por hacer':'hecho')+'</small></summary><ol class="pasos">'+pasosFiltrados(l,f).map(p=>pasoH(p,f)).join('')+'</ol>'+(l.objetos?'<div class="extra"><h4>Objetos</h4><ul class="lista">'+l.objetos.map(o=>'<li>'+esc(o)+'</li>').join('')+'</ul></div>':'')+(l.salvajes?'<div class="extra"><h4>Salvajes y notas</h4><p>'+esc(l.salvajes)+'</p></div>':'')+'</details>'}

/* ---------- Guía del dinero ---------- */
const eur=n=>Math.round(n).toLocaleString('es-ES')+' $';
const ligaTeselia=()=>!!E.hechos.castillo||(E.ligas||[]).includes('Teselia');
const ligasReales=()=>{const s=new Set(E.ligas||[]);if(ligaTeselia())s.add('Teselia');return[...s]};
function reqEstado(r){if(r.tipo==='hoy')return[true,'Lo puedes hacer ya'];if(r.tipo==='medallas')return E.medallas>=r.n?[true,'Lo puedes hacer ya']:[false,'Con '+r.n+' medallas'];if(r.tipo==='liga')return ligasReales().includes(r.r)?[true,'Lo puedes hacer ya']:[false,'Tras ganar la Liga de '+r.r];if(r.tipo==='capital')return E.dinero>=r.n?[true,'Lo puedes hacer ya']:[false,'Con '+eur(r.n)+' de reserva'];if(r.tipo==='todas')return ligasReales().length>=5?[true,'Lo puedes hacer ya']:[false,'Con las 5 regiones'];return[false,r.t]}
function simular(){const regs=[...new Set([...ligasReales(),...(E.sim||[])])],mins=E.simMin||60,b=DIN.boosts.find(x=>x.id===(E.simB||'am'))||DIN.boosts[0];
 const actos=regs.flatMap(r=>{const d=DIN.regiones[r];return[{n:'Gimnasios de '+r,p:d.gyms,m:d.gmin},{n:'Liga de '+r,p:d.liga,m:d.lmin},{n:'Entrenadores ricos de '+r,p:d.ruta,m:d.rmin}]}).sort((x,y)=>y.p/y.m-x.p/x.m);
 let queda=mins;const elegidos=[];for(const a of actos){if(a.m<=queda){elegidos.push(a);queda-=a.m}}
 const usados=mins-queda,base=elegidos.reduce((s,a)=>s+a.p,0),horas=Math.ceil(usados/60),neto=base*b.x-b.coste*horas;
 return{regs,mins,b,elegidos,usados,base,horas,neto}}
function diasHasta(meta,neto){if(E.dinero>=meta)return'Ya lo tienes';if(neto<=0)return'—';const d=Math.ceil((meta-E.dinero)/neto);return d+(d===1?' día':' días')}
const D={
 resumen(){const sig=DIN.hitos.find(h=>E.dinero<h.v)||DIN.hitos[DIN.hitos.length-1],pct=Math.min(1,E.dinero/sig.v);
  return `<section class="bloque"><h2>Lo primero que debes saber</h2><ul class="lista">${DIN.verdades.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul></section>
  <section class="seccion"><header><h2>Tus metas</h2><span class="nota">Tienes ${eur(E.dinero)}</span></header><div class="metas">${DIN.hitos.map(h=>{const ok=E.dinero>=h.v,act=h===sig;return `<article class="meta${ok?' ok':''}${act?' act':''}"><h3>${esc(h.t)}</h3><p>${esc(h.d)}</p>${act?`<span class="bv"><i style="transform:scaleX(${pct.toFixed(3)})"></i></span><small class="nota">Te faltan ${eur(h.v-E.dinero)}</small>`:ok?'<small class="nota">Conseguido</small>':''}</article>`}).join('')}</div></section>
  <section class="seccion"><h2>La estrategia, paso a paso</h2><div class="lugares sueltos">${DIN.plan.map((f,i)=>`<details class="lugar" id="pl-${i}"${i===0?' open':''}><summary><span>${esc(f.t)}<small>${esc(f.cuando)}</small></span></summary><ol class="numerada">${f.pasos.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol></details>`).join('')}</div></section>
  <section class="seccion"><h2>Según el tiempo que tengas</h2><div class="metas">${DIN.dia.map(x=>`<article class="meta"><h3>${esc(x.t)}</h3><p>${esc(x.d)}</p></article>`).join('')}</div></section>
  <section class="bloque aviso-b"><h2>Lo que nunca debes hacer</h2><ul class="lista">${DIN.peligros.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul></section>`},
 plan(){const s=simular(),max=Math.max(1,...s.elegidos.map(a=>a.p)),regs=Object.keys(DIN.regiones),reales=ligasReales();
  return `<section class="seccion"><h2>Calcula tu día</h2><p class="nota">Elige regiones, tiempo y potenciador, y te digo qué hacer en orden. Las cifras son de base de la comunidad; no restan curas ni el tiempo de preparación.</p>
  <div class="bloque"><h3>Regiones con la Liga ganada</h3><div class="chips" role="group" aria-label="Ligas ganadas">${regs.map(r=>{const on=reales.includes(r);return `<button class="chip" data-liga="${r}" aria-pressed="${on}">${r}</button>`}).join('')}</div>
  <h3>Y si además ganara…</h3><div class="chips" role="group" aria-label="Regiones para simular">${regs.filter(r=>!reales.includes(r)).map(r=>`<button class="chip" data-sim="${r}" aria-pressed="${(E.sim||[]).includes(r)}">${r}</button>`).join('')||'<span class="nota">Ya las tienes todas.</span>'}</div>
  <h3>Tiempo al día</h3><div class="chips" role="group" aria-label="Minutos al día">${[15,30,60,120,240,360].map(m=>`<button class="chip" data-mins="${m}" aria-pressed="${s.mins===m}">${m<60?m+' min':m/60+' h'}</button>`).join('')}</div>
  <h3>Potenciador</h3><div class="chips" role="group" aria-label="Potenciador">${DIN.boosts.map(b=>`<button class="chip" data-boost2="${b.id}" aria-pressed="${s.b.id===b.id}">${b.nom}${b.coste?' · '+eur(b.coste)+'/h':''}</button>`).join('')}</div></div></section>
  <section class="resumen-sim"><div class="dato grande"><span>Al día</span><b data-cnt="simd" data-v="${Math.round(s.neto)}">${Math.round(s.neto).toLocaleString('es-ES')}</b><small>$ netos, ya descontado el potenciador</small></div><div class="dato grande"><span>A la semana</span><b data-cnt="simw" data-v="${Math.round(s.neto*7)}">${Math.round(s.neto*7).toLocaleString('es-ES')}</b><small>$ si juegas los 7 días</small></div><div class="dato grande"><span>1 millón</span><b>${diasHasta(1e6,s.neto)}</b><small>desde lo que tienes</small></div><div class="dato grande"><span>10 millones</span><b>${diasHasta(1e7,s.neto)}</b><small>con este mismo ritmo</small></div></section>
  ${s.regs.length?`<section class="seccion"><header><h2>Qué hacer, en este orden</h2><span class="nota">${s.usados} de ${s.mins} min</span></header>${s.elegidos.length?`<ol class="orden">${s.elegidos.map((a,i)=>`<li style="--d:${i*40}"><div><b>${esc(a.n)}</b><small class="nota">${a.m} min · ${eur(a.p/a.m)} por minuto</small></div><b>${eur(a.p*s.b.x)}</b><span class="bv"><i style="transform:scaleX(${(a.p/max).toFixed(3)})"></i></span></li>`).join('')}</ol>`:'<p class="nota">Con este tiempo no cabe nada completo. Prueba con más minutos.</p>'}</section>`:`<section class="bloque"><h2>Aún no se ha abierto la rutina</h2><p>Todavía no has ganado ninguna Liga. Pulsa Teselia en "Y si además ganara…" para ver lo que te espera. Mientras tanto, tu dinero viene de la historia.</p></section>`}
  <p class="nota">Los días suponen que tu equipo gana esos combates; al principio irás más lento. Se usa un potenciador por cada hora de juego. La Moneda Amuleto suele compensar; los Riches Charm solo si la hora va llena de combates que pagan. Los métodos con varios personajes o cuentas no se suman.</p>`},
 metodos(){const G=[['hoy','Para hoy, con tu equipo'],['pronto','Muy pronto'],['liga','Tras la Liga de Teselia'],['region','Con otras regiones y a largo plazo']];
  return `<div class="chips" role="group" aria-label="Filtro"><button class="chip" data-solo="0" aria-pressed="${!soloYa}">Todos (${DIN.metodos.length})</button><button class="chip" data-solo="1" aria-pressed="${soloYa}">Lo que puedo hacer ya (${DIN.metodos.filter(m=>reqEstado(m.req)[0]).length})</button></div>
  ${G.map(([k,g])=>{const ms=DIN.metodos.filter(m=>m.grupo===k&&(!soloYa||reqEstado(m.req)[0]));return ms.length?`<section class="seccion"><h2>${g}</h2><div class="lugares sueltos">${ms.map(metodoH).join('')}</div></section>`:''}).join('')}`},
 gtl(){const g=DIN.gtl;return `<section class="bloque"><h2>Qué es y cómo funciona</h2><p>El GTL es una tienda entre jugadores: unos publican y otros compran.</p><ul class="lista">${g.hechos.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section>
  <section class="bloque"><h2>Cuánto cobra el juego</h2><ul class="lista">${g.comision.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p class="aviso">${esc(g.regla)}</p></section>
  <section class="seccion"><h2>Calculadora de venta</h2><div class="bloque"><div class="calc"><label for="pv">Precio de venta</label><input id="pv" class="num" inputmode="numeric" value="${E.gtlV||''}" placeholder="100000"><label for="pc">Lo que te costó</label><input id="pc" class="num" inputmode="numeric" value="${E.gtlC||''}" placeholder="50000"><label for="tp">Es</label><select id="tp">${['Pokémon','Objeto'].map(x=>`<option${(E.gtlT||'Pokémon')===x?' selected':''}>${x}</option>`).join('')}</select></div><p id="gtlres" aria-live="polite">${gtlCalc()}</p><p class="nota">Usa la comisión de la wiki. Si el juego te muestra otra, manda el juego.</p></div></section>`},
 equipos(){return `<section class="seccion"><h2>Equipos, de menos a más</h2><div class="metas">${DIN.equipos.map(q=>`<article class="meta"><h3>${esc(q.nom)}</h3><p class="nota">Para: ${esc(q.para)}</p><ul class="lista">${q.lista.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p class="aviso">${esc(q.nota)}</p></article>`).join('')}</div><p class="nota">Antes de comprar nada, busca el Pokémon y mira movimientos, habilidad y naturaleza. Los precios cambian.</p></section>
  <section class="seccion"><header><h2>Ruta de los 40 gimnasios</h2><span class="nota">Equipo de Strawee · 1 h 45</span></header><p class="nota">Primero van los dos que debes sacar. La guía original cuenta más líderes en Teselia de los que enumera, por ejemplo por Morimoto.</p><div class="lugares sueltos">${DIN.rutaGimnasios.map((r,i)=>`<details class="lugar" id="rg-${i}"><summary><span>${esc(r.r)}<small>${r.g.length} paradas</small></span><small>${eur(r.pay)}</small></summary><div class="tablazo sin"><table class="tabla compacta"><tbody>${r.g.map((g,j)=>`<tr><td>${j+1}</td><td>${esc(g[0])}</td><td>${esc(g[1])}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</div></section>`},
 esperas(){return `<section class="seccion"><header><h2>Temporizadores</h2><span class="nota">Pulsa al terminar y te cuenta la espera</span></header><div class="timers" id="timers">${timersH()}</div></section>
  <section class="bloque"><h2>¿6 o 18 horas para la Liga?</h2><p>Las fuentes no coinciden: ShoutWiki dice 6 horas y PikaMMO, 18. Antes te di las 18 como seguras, y no lo están. Al repetirla, mira lo que dice el juego y elige aquí.</p><div class="chips" role="group" aria-label="Espera de la Liga">${[6,18].map(h=>`<button class="chip" data-ligah="${h}" aria-pressed="${(E.ligaH||18)===h}">${h} horas</button>`).join('')}</div></section>`},
 dicc(){return `<section class="seccion"><h2>Diccionario</h2><dl class="dicc">${DIN.glosario.map(g=>`<div><dt>${esc(g[0])}</dt><dd>${esc(g[1])}</dd></div>`).join('')}</dl></section>`}};
function gtlCalc(){const v=+(E.gtlV||0),c=+(E.gtlC||0);if(!v)return'Escribe un precio y te digo cuánto te queda.';const obj=(E.gtlT||'Pokémon')==='Objeto',f=v>500000?25000:(obj?(v>2000?v*.05:100):(v>20000?v*.05:1000)),g=v-f-c;return 'Comisión: <b>'+eur(f)+'</b>. Te quedan <b class="'+(g>=0?'ok':'mal')+'">'+eur(g)+'</b> de '+(g>=0?'ganancia':'pérdida')+'.'}
function metodoH(m){const[ok,txt]=reqEstado(m.req);return `<details class="lugar met" id="m-${m.id}"><summary><span>${esc(m.nom)}<small>${esc(m.paga)}</small></span><span class="pill ${ok?'si':'no'}">${esc(txt)}</span></summary><div class="met-c"><p class="frase">${esc(m.frase)}</p><dl class="fichita"><div><dt>Tiempo</dt><dd>${esc(m.tiempo)}</dd></div><div><dt>Dificultad</dt><dd>${esc(m.dificultad)}</dd></div><div><dt>Fuente</dt><dd>${{pika:'PikaMMO',shout:'ShoutWiki',wiki:'pokemmo.wiki',t:'Tu partida'}[m.fuente]||m.fuente}</dd></div></dl><h4>Qué necesitas</h4><ul class="lista">${m.necesitas.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><h4>Paso a paso</h4><ol class="numerada">${m.pasos.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><h4>Errores típicos</h4><ul class="lista">${m.errores.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div></details>`}

/* ---------- Objetos ---------- */
const tengo=n=>!!(E.tengo||{})[n];
const irBtn=ir=>ir?'<button class="mini" data-ir="'+ir+'">Ver en la ruta</button>':'';
const tengoBtn=n=>'<button class="mini tengo'+(tengo(n)?' si':'')+'" data-tengo="'+esc(n)+'" aria-pressed="'+tengo(n)+'">'+(tengo(n)?'Lo tengo':'Lo quiero')+'</button>';
function monObj(x){const m=E.equipo.find(e=>e.sp===x.sp||e.sp===x.evoDe);if(!m)return'';const e=ESPECIES[m.sp];return `<article class="mon"><div class="mon-top">${ani(e.id)}<div><h3>${esc(m.sp)}${m.sp!==x.sp?` <span class="nota">pronto ${esc(x.sp)}</span>`:''}</h3><div class="tipos">${e.t.map(tipoH).join('')}</div></div></div>
  <div class="obj-rec"><span class="et">Ahora</span><b>${esc(x.ahora)}</b><p>${esc(x.por)}</p><p class="nota">Dónde: ${esc(x.donde)}</p></div><div class="obj-rec"><span class="et luego">Después</span><b>${esc(x.luego)}</b><p>${esc(x.luegoPor)}</p></div><p class="aviso">${esc(x.mov)}</p></article>`}
const O={
 equipo(){return `<section class="bloque"><h2>Antes de empezar</h2><ul class="lista">${OBJ.reglas.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section>
  <section class="seccion"><header><h2>Qué lleva cada Pokémon</h2>${pruebaH('a')}</header><p class="nota">Es mi consejo para tu equipo real, con objetos que puedes conseguir en Teselia. Se ajusta a tus evoluciones.</p><div class="equipo">${OBJ.pokemon.map(monObj).join('')}</div></section>`},
 equipables(){const L=OBJ.equipables.filter(o=>objFiltro==='todo'||(objFiltro==='falta'&&!tengo(o.es))||(objFiltro==='tengo'&&tengo(o.es)));
  return `<div class="chips" role="group" aria-label="Filtro"><button class="chip" data-ofil="todo" aria-pressed="${objFiltro==='todo'}">Todos (${OBJ.equipables.length})</button><button class="chip" data-ofil="falta" aria-pressed="${objFiltro==='falta'}">Los que me faltan</button><button class="chip" data-ofil="tengo" aria-pressed="${objFiltro==='tengo'}">Los que tengo</button></div>
  <div class="objetos">${L.map(o=>`<article class="obj"><header><h3>${esc(o.es)}<small>${esc(o.en)}</small></h3>${tengoBtn(o.es)}</header><p>${esc(o.efecto)}</p><dl class="fichita col"><div><dt>Mejor en</dt><dd>${esc(o.para)}</dd></div><div><dt>Dónde</dt><dd>${esc(o.donde)}</dd></div>${o.cond?`<div><dt>Requisito</dt><dd>${esc(o.cond)}</dd></div>`:''}</dl><div class="fila-acc">${pruebaH(o.p)}${irBtn(o.ir)}</div></article>`).join('')||'<p class="nota">Nada con este filtro.</p>'}</div>`},
 evolucion(){return `<section class="seccion"><h2>Tus evoluciones y las piedras</h2><div class="metas">${OBJ.evolucion.map(x=>`<article class="meta"><h3>${esc(x.sp)}</h3><p>${esc(x.como)}</p>${pruebaH(x.p)}</article>`).join('')}</div></section>`},
 mt(){return `<section class="bloque"><h2>Cómo funcionan</h2><p>Las MT te dejan enseñar un ataque. Tus notas dicen que en PokeMMO se gastan al usarlas, así que dáselas solo a quien las vaya a usar siempre. Si cambias de idea, el Recordador de Movimientos de cualquier Centro Pokémon recupera ataques aprendidos por nivel a cambio de Escamas Corazón. Antes de gastar una, comprueba que el Pokémon pueda aprenderla: lo dice el propio juego.</p></section>
  <section class="seccion"><h2>Las MT de Teselia</h2><div class="tablazo"><table class="tabla"><thead><tr><th>MT</th><th>Dónde</th><th>Para quién</th><th></th></tr></thead><tbody>${OBJ.mt.map(m=>`<tr><td>${esc(m.es)}</td><td>${esc(m.donde)}</td><td>${esc(m.para)}</td><td>${tengoBtn('MT '+m.es)}</td></tr>`).join('')}</tbody></table></div></section>`},
 mios(){return `<section class="seccion"><h2>Objetos para ti</h2><p class="nota">Los que te sirven a ti, no a un Pokémon: moverte, encontrar cosas y ganar más.</p><div class="objetos">${OBJ.para_mi.map(o=>`<article class="obj"><header><h3>${esc(o.es)}</h3>${tengoBtn(o.es)}</header><p>${esc(o.para)}</p><dl class="fichita col"><div><dt>Dónde</dt><dd>${esc(o.donde)}</dd></div></dl><div class="fila-acc">${pruebaH(o.p)}${irBtn(o.ir)}</div></article>`).join('')}</div></section>`},
 botiquin(){return `<section class="seccion"><h2>Qué llevar en la mochila</h2><div class="metas">${OBJ.botiquin.map(b=>`<article class="meta"><h3>${esc(b.t)}</h3><ul class="lista">${b.lista.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>${pruebaH(b.p)}</article>`).join('')}</div></section>
  <section class="seccion"><h2>Lo que mejora a tus Pokémon</h2><div class="metas">${OBJ.mejoras.map(b=>`<article class="meta"><h3>${esc(b.t)}</h3><p>${esc(b.d)}</p>${pruebaH(b.p)}</article>`).join('')}</div></section>`}};

/* ---------- Personaje ---------- */
function resultCos(){const w=norm(cosQ).trim(),lista=w?Object.entries(COS).flatMap(([g,v])=>v.filter(x=>norm(x).includes(w)).map(x=>[x,g])):(COS[cosG]||[]).map(x=>[x,cosG]);return lista.length?'<ul class="cos">'+lista.slice(0,400).map(([x,g])=>'<li>'+esc(x)+(w?' <small>'+esc(g)+'</small>':'')+'</li>').join('')+'</ul>':'<p class="nota">No aparece en el catálogo.</p>'}
const P={
 ficha(){const f=E.ficha||{};return `<section class="ficha pj"><div class="ficha-a"><div class="sub">Ficha del entrenador</div><h1>Tatoide</h1><p class="nota">Calvo con barba, camiseta roja, vaqueros grises y zapatillas rojas, según tu captura.</p><div class="medallas" aria-hidden="true">${MEDALLAS.map((m,i)=>`<span class="medalla${i<E.medallas?' on':''}" style="--c:${m[2]}">${i+1}</span>`).join('')}</div></div>
   <div class="ficha-b"><div class="dato"><span>Pokédex</span><input id="f-dex" inputmode="numeric" value="${f.dex??17}" aria-label="Pokémon en la Pokédex"><small>Toca para corregirlo</small></div><div class="dato"><span>Dinero</span><b>${E.dinero.toLocaleString('es-ES')}</b><small>Se edita en Ahora</small></div><div class="dato"><span>Puntos de Batalla</span><input id="f-bp" inputmode="numeric" value="${f.bp??0}" aria-label="Puntos de Batalla"><small>Toca para corregirlo</small></div><div class="dato"><span>Tiempo</span><input id="f-h" inputmode="numeric" value="${f.h??14}" aria-label="Horas jugadas"><small>Horas</small></div><div class="dato limite"><span>Máxima Obediencia</span><b>Nv.${lim()}</b><small>Según tus medallas</small></div><div class="dato"><span>Ficha</span><b>6/7/26</b><small>Fecha de tu ficha</small></div></div></section>
  <section class="seccion"><h2>Qué significa cada dato</h2><dl class="dicc">${PER.ficha_ayuda.map(g=>`<div><dt>${esc(g[0])}</dt><dd>${esc(g[1])}</dd></div>`).join('')}</dl></section>`},
 mejorar(){return `<section class="seccion"><h2>Cómo mejorar tu personaje</h2><p class="nota">Tu entrenador no sube de nivel ni tiene estadísticas: mejora ganando medallas, ampliando lo que puede hacer y juntando comodidades.</p><div class="metas">${PER.mejorar.map(x=>`<article class="meta"><h3>${esc(x.t)}</h3><p>${esc(x.d)}</p>${pruebaH(x.p)}</article>`).join('')}</div></section>`},
 look(){return `<section class="seccion"><h2>Cómo cambiar tu aspecto, paso a paso</h2><div class="bloque"><ol class="numerada sin">${PER.look_pasos.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol></div></section>
  <section class="seccion"><h2>Qué se puede cambiar</h2><div class="metas">${PER.look_base.map(x=>`<article class="meta"><h3>${esc(x.t)}</h3><p>${esc(x.d)}</p>${pruebaH(x.p)}</article>`).join('')}</div></section>
  <section class="seccion"><h2>De dónde sale cada cosa</h2><div class="metas">${PER.fuentes.map(x=>`<article class="meta"><h3>${esc(x.t)}</h3><p>${esc(x.d)}</p>${pruebaH(x.p)}</article>`).join('')}</div></section>
  <section class="seccion"><h2>Tu plan de estilo</h2><div class="metas">${PER.plan.map(x=>`<article class="meta"><h3>${esc(x.t)}</h3><p>${esc(x.d)}</p></article>`).join('')}</div></section>
  <section class="bloque aviso-b"><h2>Con cuidado</h2><ul class="lista">${PER.mal.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section>
  <section class="bloque"><h2>Lo que no he podido confirmar</h2><ul class="lista">${PER.dudas.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section>`},
 catalogo(){const tot=Object.values(COS).reduce((s,v)=>s+v.length,0);return `<section class="seccion"><header><h2>Catálogo de cosméticos</h2><span class="nota">${tot} nombres de tu propio cliente</span></header><p class="nota">No dice el precio ni dónde sale: con el nombre, búscalo en el GTL. Algunos ya no se consiguen.</p>
  <div class="busca"><label for="cq">Buscar por nombre</label><input id="cq" type="search" placeholder="Alas, Gorra, Dragón…" value="${esc(cosQ)}" autocomplete="off"></div>
  <div class="chips" role="group" aria-label="Parte del cuerpo">${Object.keys(COS).map(g=>`<button class="chip" data-cos="${esc(g)}" aria-pressed="${cosG===g}">${esc(g)} (${COS[g].length})</button>`).join('')}</div><div id="cosres" aria-live="polite">${resultCos()}</div></section>
  <section class="seccion"><h2>Tienda de Regalos: precios fijos</h2><div class="tablazo"><table class="tabla compacta"><tbody>${PER.tienda.map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td></tr>`).join('')}</tbody></table></div><p class="nota">Según la wiki (julio de 2026). Antes de pagar, mira el precio en el juego.</p></section>`}};

/* ---------- Vistas ---------- */
const V={
 ahora(){const ev=cuentaEvento(),sig=RIV.find(r=>r.id===rivalSiguiente());
  return `<section class="ficha" aria-label="Ficha de entrenador"><div class="ficha-a"><div class="hojas ${temporada()}" aria-hidden="true">${[8,22,37,51,66,79,92].map((x,i)=>`<i style="left:${x}%;animation-delay:-${i*2.3}s;animation-duration:${11+i%3*3}s"></i>`).join('')}</div><div class="sub">PokeMMO · Teselia</div><h1>Tatoide</h1><div class="medallas" role="group" aria-label="Medallas de Teselia">${MEDALLAS.map((m,i)=>`<button class="medalla${i<E.medallas?' on':''}" style="--c:${m[2]}" data-med="${i+1}" title="${m[0]} · ${m[1]}" aria-label="Medalla ${m[0]}, ${i<E.medallas?'conseguida':'pendiente'}" aria-pressed="${i<E.medallas}">${i+1}</button>`).join('')}</div><p class="nota">Pulsa una medalla al ganarla: el límite, la ruta y el combate siguiente cambian solos.</p><div class="prog" aria-label="Progreso de Teselia"><span class="nota">Teselia</span><span class="bv"><i data-pct="${progreso()}" style="transform:scaleX(${progreso()})"></i></span><b>${Math.round(progreso()*100)} %</b></div></div>
   <div class="ficha-b"><div class="dato limite"><span>Límite</span><b>Nv.<span data-cnt="lim" data-v="${lim()}">${lim()}</span></b><small>Con la siguiente medalla: Nv.${sigLim()}</small></div><div class="dato"><span>Dinero</span><input id="dinero" inputmode="numeric" aria-label="Dinero" value="${E.dinero.toLocaleString('es-ES')}"><small>Toca para corregirlo</small></div><div class="dato"><span>Temporada</span><b>${temporada()}</b><small>Cambia cada mes y altera las apariciones</small></div><div class="dato"><span>Pendiente</span><b data-cnt="pend" data-v="${pendientes().length}">${pendientes().length}</b><small>pasos hasta acabar Teselia</small></div></div></section>
  ${ev?`<section class="evento"><div class="ev-txt"><h2>Halloween termina en <span class="cuenta">${ev}</span></h2><p>A tu nivel, lo que merece la pena: los <b>30 Gatabazas</b> (cosmético y un Zorua Alfa que se puede capturar) y las <b>20 flamas</b> de esta región (combate Alfa secreto). Lo demás pide equipos de Nv.80: déjalo pasar. Fin: 13 nov, 23:59 UTC.</p></div><div class="ev-cont">${[['gat','Gatabazas','encontrados'],['fla','Flamas','quedan'],['inc','Incursiones','hechas']].map(([k,n,s])=>{const v=E.evento[k],m=EV_MAX[k];return `<div class="ev-c"><span>${n}</span><div class="nv"><button class="mini" data-ev="${k}:-1" aria-label="Restar a ${n}">−</button><b>${v}/${m}</b><button class="mini" data-ev="${k}:1" aria-label="Sumar a ${n}">+</button></div><small>${s}</small><span class="bv"><i style="transform:scaleX(${v/m})"></i></span></div>`}).join('')}</div></section>`:''}
  <div class="dos"><section class="seccion"><header><h2>Lo siguiente</h2><a href="#ruta">Ver la ruta entera</a></header><ol class="pasos">${RUTA.fases.filter(f=>f.med<10).flatMap(f=>obligatorios(f).filter(p=>!pasoHecho(p,f)).map(p=>[p,f])).slice(0,5).map(([p,f])=>pasoH(p,f)).join('')||'<li class="nota">Teselia completa.</li>'}</ol></section>
  <section class="seccion"><header><h2>Próximo rival: ${esc(sig.nom)}</h2><a href="#combate">Abrir matriz</a></header><div class="plan"><p>${esc(sig.nota)}</p>${planDe(sig)}</div></section></div>
  <section class="seccion"><header><h2>Tu equipo</h2><span class="nota">Toca un movimiento para cambiarlo.</span></header><div class="equipo">${E.equipo.map(monH).join('')}</div></section>`},
 ruta(){const n=f=>{const o=f.lugares.flatMap(l=>l.pasos);return o.filter(p=>pasoHecho(p,f)).length+'/'+o.length};const act=RUTA.fases.find(f=>!faseSuperada(f));
  return `<header class="cabeza"><h1>Ruta de Teselia</h1><p>De Pueblo Arcilla a la Liga y lo que viene después, lugar por lugar. Las fases superadas se marcan solas, pero sus opcionales siguen abiertos por si quieres volver a por ellos.</p></header>
  <div class="leyenda">${Object.keys(PRUEBAS).map(pruebaH).join('')}<span>Los nombres en inglés te ayudan a buscar: alguno en español puede variar.</span></div>
  <div class="busca"><label for="q">Buscar en toda la guía</label><input id="q" type="search" placeholder="Piedra Trueno, Litwick, Surf, Swanna…" value="${esc(q)}" autocomplete="off"><div id="resultados" aria-live="polite">${resultados()}</div></div>
  ${mapa()}
  <div class="chips" role="group" aria-label="Filtrar pasos">${[['todo','Todo'],['pend','Por hacer'],['opc','Opcionales pendientes']].map(([k,v])=>`<button class="chip" data-filtro="${k}" aria-pressed="${filtro===k}">${v}</button>`).join('')}</div>
  <div class="seccion">${RUTA.fases.map(f=>{const ls=f.lugares.map((l,i)=>[l,i]).filter(([l])=>filtro==='todo'||pasosFiltrados(l,f).length);if(!ls.length)return'';const ab=filtro!=='todo'||f===act;return `<details class="fase" id="${f.id}"${ab?' open':''}><summary>${esc(f.nom)}<small>${esc(f.lim)} · ${n(f)}</small></summary><div class="lugares">${ls.map(([l,i])=>lugarH(l,f,filtro!=='todo'||(f===act&&l===f.lugares.find(x=>x.pasos.some(p=>!pasoHecho(p,f)))),i)).join('')}</div></details>`}).join('')||'<p class="nota">Nada pendiente con este filtro.</p>'}</div>`},
 combate(){const r=RIV.find(x=>x.id===(rivalSel||rivalSiguiente()));
  return `<header class="cabeza"><h1>Matriz de combate</h1><p>Tus seis, con tus movimientos reales, ordenados de mejor a peor contra cada Pokémon del rival. Si cambias evolución o ataques en tu equipo, se recalcula.</p></header>
  <div class="chips" role="group" aria-label="Elegir rival">${RIV.map(x=>`<button class="chip" data-rival="${x.id}" aria-pressed="${x.id===r.id}">${esc(x.nom)}</button>`).join('')}</div>
  <section class="seccion"><header><h2>${esc(r.nom)}${pruebaH(r.prueba)}</h2><span class="nota">${esc(r.lugar)}</span></header><p>${esc(r.nota)}</p><div class="chips" role="group" aria-label="Vista">${[['versus','Versus'],['tabla','Tabla completa']].map(([k,v])=>`<button class="chip" data-modo="${k}" aria-pressed="${modoCombate===k}">${v}</button>`).join('')}</div><div class="plan"><h3>Lectura rápida</h3>${planDe(r)}</div>${modoCombate==='versus'?versus(r):matriz(r)}</section>
  <section class="seccion"><header><h2>Calculadora de tipos</h2><span class="nota">Elige uno o dos tipos del rival</span></header><div class="selector" role="group" aria-label="Tipos del rival">${TT.map(t=>`<button class="tipo" style="--c:var(--t-${t})" data-tipo="${t}" aria-pressed="${tiposSel.includes(t)}">${TN[t]}</button>`).join('')}</div><div class="res">${tablaTipos()}</div><p class="nota">La tabla no ve habilidades: Levitación anula Tierra, Absorbe Agua cura con Agua.</p></section>`},
 objetos(){const SEC=[['equipo','Mis Pokémon'],['equipables','Equipables'],['evolucion','Evolución'],['mt','MT'],['mios','Para mí'],['botiquin','Botiquín y mejoras']];
  return `<header class="cabeza"><h1>Objetos</h1><p>Qué conseguir, dónde y para quién. Marca lo que ya tienes y filtra lo que te falta. En Personaje tienes lo que es solo de tu entrenador.</p></header>
  <div class="chips" role="group" aria-label="Secciones de objetos">${SEC.map(([k,v])=>`<button class="chip" data-osec="${k}" aria-pressed="${objSec===k}">${v}</button>`).join('')}</div>${O[objSec]()}`},
 personaje(){const SEC=[['ficha','Ficha'],['mejorar','Mejorar'],['look','Aspecto'],['catalogo','Catálogo']];
  return `<header class="cabeza"><h1>Personaje</h1><p>Todo lo que es de tu entrenador y no de tus Pokémon: tu ficha, cómo mejorar y cómo cambiar de aspecto.</p></header>
  <div class="chips" role="group" aria-label="Secciones de personaje">${SEC.map(([k,v])=>`<button class="chip" data-psec="${k}" aria-pressed="${perSec===k}">${v}</button>`).join('')}</div>${P[perSec]()}`},
 dinero(){const SEC=[['resumen','Estrategia'],['plan','Mi plan'],['metodos','Todos los métodos'],['gtl','GTL'],['equipos','Equipos'],['esperas','Esperas'],['dicc','Diccionario']];
  return `<header class="cabeza"><h1>Guía del dinero</h1><p>Todo lo que puedes hacer para ganar mucho dinero sin arriesgar tu cuenta, explicado paso a paso. Las cifras salen de guías de la comunidad y cambian con el mercado.</p></header>
  <div class="chips" role="group" aria-label="Secciones de dinero">${SEC.map(([k,v])=>`<button class="chip" data-din="${k}" aria-pressed="${dinSec===k}">${v}</button>`).join('')}</div>
  ${D[dinSec]()}`},
 regiones(){const col=Object.keys(CAPS);return `<header class="cabeza"><h1>Regiones</h1><p>Cada región lleva su propio contador. Un Pokémon por encima del límite se desmaya al salir a combatir, venga de donde venga.</p></header>
  <section class="seccion"><h2>Límites de obediencia</h2><div class="tablazo"><table class="tabla"><thead><tr><th>Medallas</th>${col.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${[...Array(9).keys()].map(i=>`<tr><td>${i}</td>${col.map(c=>`<td class="${c==='Teselia'&&i===E.medallas?'aqui':''}">${CAPS[c][i]}</td>`).join('')}</tr>`).join('')}<tr><td>Liga</td>${col.map(()=>'<td>100</td>').join('')}</tr></tbody></table></div><p class="nota">Comprobada contra la guía de la comunidad (2 ago 2026) y tu ficha: 5 medallas, Nv.38. En Johto, Ho-Oh sube el límite a 55 antes de la Liga.</p></section>
  <section class="seccion"><h2>Orden propuesto</h2><div class="tablazo"><table class="tabla"><thead><tr><th></th><th>Región</th><th>Por qué</th></tr></thead><tbody><tr><td>1</td><td class="aqui">Teselia</td><td>Ya vas por la medalla 6. Rematar la Liga abre la rutina de dinero.</td></tr><tr><td>2</td><td>Kanto</td><td>Ya la conoces y tiene muchos entrenadores que pagan bien.</td></tr><tr><td>3</td><td>Hoenn</td><td>La Liga mejor pagada, Dittos para criar y Nincada para dinero temprano.</td></tr><tr><td>4</td><td>Sinnoh</td><td>Pokédex y exclusivos. Desde julio de 2026 tiene tablas de Recogida.</td></tr><tr><td>5</td><td>Johto</td><td>Requiere HeartGold, que ya tienes cargado. Ho-Oh se puede repetir cada semana.</td></tr></tbody></table></div></section>
  <section class="seccion"><h2>Lecciones de la primera vuelta</h2><div class="bloque"><ul class="lista"><li><b>Liga de Kanto a Nv.86:</b> la paliza de Lorelei. Lleva el equipo parejo antes de entrar.</li><li><b>Weezing con Levitación:</b> Terremoto no le toca. Eelektross, igual.</li><li><b>Kingdra</b> solo es débil a Dragón. Hielo y Eléctrico no ayudan.</li><li><b>Gengar:</b> Lucha y Normal no le tocan.</li><li><b>Comprar en el GTL:</b> mira movimientos, PP y habilidad antes que el nivel. El Mamoswine Nv.76 con Terremoto ganaba al Nv.80 sin él.</li></ul></div></section>
  <section class="seccion"><h2>Por venir</h2><div class="bloque"><p><b>Blanco 2 / Negro 2.</b> Una wiki de la comunidad cita a Kyu apuntando al último trimestre de 2026, como región aparte de Teselia. Sin fecha confirmada.</p></div></section>`},
 mas(){return `<header class="cabeza"><h1>Más</h1><p>Regiones, tu progreso en cada aparato, las reglas de juego limpio, los mods y de dónde salen los datos.</p></header>
  <div class="fila-acc"><a class="btn enlace" href="#regiones">Regiones y límites de nivel</a></div>
  <section class="seccion"><h2>Tu progreso en otro aparato</h2><div class="bloque"><p>Lo que marcas se guarda en este navegador. Para llevarlo a otro aparato, copia el código aquí y pégalo allí. La web también funciona sin conexión una vez abierta.</p><div class="fila-acc"><button class="btn" id="copiar">Copiar mi progreso</button>${instalar?'<button class="btn sec" id="instalar">Instalar como aplicación</button>':''}</div><label for="codigo" class="nota">Pega aquí un código de otro aparato</label><textarea id="codigo" rows="3" spellcheck="false"></textarea><div class="fila-acc"><button class="btn sec" id="pegar">Cargar este código</button></div><p class="nota" role="status">${esc(msg)}</p></div></section>
  <div class="dos"><section class="seccion"><h2>Juego limpio</h2><div class="bloque"><p>Esta es una segunda vuelta desde cero: el equipo y el dinero se ganan jugando.</p><ul class="lista"><li><b>Nunca</b> compres dinero ni Pokémon por fuera, por barato que sea.</li><li><b>Nunca</b> uses bots. Algunas webs que salen al buscar guías los venden: aquí no son fuente.</li><li><b>Si quieres poner dinero real,</b> la vía oficial es la tienda del juego.</li><li><b>Intercambios:</b> para evolucionar a Golem, alguien de confianza y objetos a la vista.</li></ul></div></section>
  <section class="seccion"><h2>Mods tras el parche del 30 de octubre</h2><div class="tablazo"><table class="tabla compacta"><thead><tr><th>Mod</th><th>Estado</th><th>Nota</th></tr></thead><tbody><tr><td>Tema Rojo Fuego</td><td>Funciona</td><td>Adaptado a la barra nueva. Probado en partida</td></tr><tr><td>Iconos Gen 8</td><td>Funciona</td><td>Probado en partida</td></tr><tr><td>Sprites Stadium 2</td><td>Funciona</td><td>Probado en partida</td></tr><tr><td>Acompañantes Gen 5</td><td>Funciona</td><td>Algunas formas no cargan</td></tr><tr><td>Texto rápido</td><td>Funciona</td><td>Probado en partida</td></tr><tr><td>Música Crystal Clear</td><td>Funciona</td><td>Probado en partida</td></tr></tbody></table></div></section></div>
  <section class="seccion"><h2>De dónde salen los datos</h2><div class="bloque"><ul class="lista"><li><b>Tu partida:</b> capturas y registro del cliente.</li><li><b>Comunidad PokeMMO:</b> <a href="https://pokemmo.wiki/guides/pokemmo-level-caps-and-obedience">pokemmo.wiki</a>, <a href="https://pokemmo.shoutwiki.com/wiki/Mistralton_Gym">ShoutWiki</a>, <a href="https://www.pikammo.fr/Pokemmo/en/money">PikaMMO</a>, <a href="https://github.com/PokeMMO/PokeMMO_Mods">mods oficiales</a>.</li><li><b>Juego original:</b> <a href="https://www.serebii.net/blackwhite/plasma.shtml">Serebii</a> y <a href="https://pokemondb.net/black-white/gymleaders-elitefour">Pokémon Database</a>.</li><li><b>Sin poder leer:</b> foros y web oficial; páginas de la wiki de Aloe, Iris, castillo de N y varias rutas.</li></ul><p class="nota">Proyecto de un jugador, sin relación con PokeMMO, Nintendo ni Game Freak.</p></div></section>`}};

/* ---------- Pintado y eventos ---------- */
const vista=()=>{const h=location.hash.slice(1);return VISTAS.some(v=>v[0]===h)||OTRAS.includes(h)?h:'ahora'};
const navH=()=>VISTAS.map(([id,n])=>'<a class="nav" href="#'+id+'"'+(id===vista()?' aria-current="page"':'')+'><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="'+IC[id]+'"/></svg>'+n+'</a>').join('');
function claveFoco(){const a=document.activeElement;if(!a||a===document.body)return null;if(a.id)return '#'+a.id;for(const k of Object.keys(a.dataset||{})){const n=k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());return '[data-'+n+'="'+a.dataset[k]+'"]'}return null}
function pinta(entra=false){const y=scrollY,foco=claveFoco(),v=vista(),abiertos=[...document.querySelectorAll('#main details[open]')].map(d=>d.id);const conserva=pinta.v===v&&abiertos.length>0&&!entra;const mapaPrevio=mapaDibujado;
 const main=document.getElementById('main');main.innerHTML='<div class="vista">'+V[v]()+'</div>';if(entra)main.dataset.entra='';else delete main.dataset.entra;
 if(conserva)document.querySelectorAll('#main details').forEach(d=>{d.open=abiertos.includes(d.id)});
 pinta.v=v;if(v==='ruta')mapaDibujado=true;void mapaPrevio;
 document.getElementById('nav1').innerHTML=navH();document.getElementById('nav2').innerHTML=navH();const s=document.getElementById('sync');if(s)s.innerHTML='<b>Guardado en este aparato</b>Partida a '+esc((E.actualizado||'').slice(0,10));
 main.querySelectorAll('[data-cnt]').forEach(el=>{const k=el.dataset.cnt,val=+el.dataset.v;if(previo[k]!==undefined&&previo[k]!==val)contar(el,previo[k],val,n=>n.toLocaleString('es-ES'));previo[k]=val});
 main.querySelectorAll('[data-pct]').forEach(el=>{const val=+el.dataset.pct;if(previo.pct!==undefined)barra(el,previo.pct,val);previo.pct=val});
 if(saltar){const d=document.getElementById(saltar.f);if(d)d.open=true;const l=saltar.l&&document.getElementById(saltar.l);if(l)l.open=true;const obj=l||d;if(obj){obj.scrollIntoView({block:'start'});obj.classList.add('marca-v');destellar(obj)}saltar=null}else scrollTo(0,y);
 if(foco){try{const el=document.querySelector(foco);if(el)el.focus({preventScroll:true})}catch(e){}}}
addEventListener('hashchange',()=>{const hayDestino=!!saltar;pinta(true);if(!hayDestino)scrollTo(0,0)});
document.addEventListener('click',async ev=>{const t=ev.target;
 if(t.id==='instalar'&&instalar){instalar.prompt();instalar=null;pinta();return}
 if(t.id==='copiar'){const c=btoa(unescape(encodeURIComponent(JSON.stringify(E))));try{await navigator.clipboard.writeText(c);msg='Código copiado.'}catch(e){document.getElementById('codigo').value=c;msg='No se pudo copiar solo: selecciona el texto de arriba.'}const area=document.getElementById('codigo').value;pinta();document.getElementById('codigo').value=area;return}
 if(t.id==='pegar'){try{const o=JSON.parse(decodeURIComponent(escape(atob(document.getElementById('codigo').value.trim()))));if(!Array.isArray(o.equipo))throw 0;E=fusiona(E,o);guardar();msg='Progreso cargado.'}catch(e){msg='Ese código no es válido. Vuelve a copiarlo entero.'}pinta();return}
 const b=t.closest('[data-med],[data-nv],[data-evo],[data-mov],[data-rival],[data-tipo],[data-boost],[data-timer],[data-fase],[data-ev],[data-filtro],[data-modo],[data-ir],[data-ir-riv],[data-ir-din],[data-ir-obj],[data-ir-per],[data-osec],[data-psec],[data-ofil],[data-tengo],[data-cos],[data-din],[data-liga],[data-sim],[data-mins],[data-boost2],[data-solo],[data-ligah]');if(!b)return;const d=b.dataset;
 if(d.med){const n=+d.med,sube=n>E.medallas;E.medallas=E.medallas===n?n-1:n;guardar();pinta();if(sube){const m=MEDALLAS[n-1];celebrar({titulo:'Medalla '+m[0],sub:'Límite de nivel: '+lim()+'. Si fue sin querer, pulsa la medalla otra vez.',color:m[2]})}}
 else if(d.nv){const[i,s]=d.nv.split(':').map(Number);E.equipo[i].nv=Math.min(100,Math.max(1,E.equipo[i].nv+s));guardar();pinta()}
 else if(d.evo){const m=E.equipo[+d.evo],de=ESPECIES[m.sp],nomDe=m.sp;m.sp=de.evo;guardar();pinta();evolucionar({de:'img/animados/'+de.id+'.gif',a:'img/animados/'+ESPECIES[m.sp].id+'.gif',nomDe,nomA:m.sp,onerror(){this.onerror=null;this.src=this.src.replace('animados','sprites').replace('.gif','.png')}})}
 else if(d.mov)editaMov(...d.mov.split(':').map(Number));
 else if(d.rival){rivalSel=d.rival;pinta(true)}
 else if(d.osec){objSec=d.osec;pinta(true)}
 else if(d.psec){perSec=d.psec;pinta(true)}
 else if(d.ofil){objFiltro=d.ofil;pinta()}
 else if(d.tengo){E.tengo=E.tengo||{};E.tengo[d.tengo]=!E.tengo[d.tengo];guardar();pinta()}
 else if(d.cos){cosG=d.cos;cosQ='';pinta()}
 else if(d.din){dinSec=d.din;pinta(true)}
 else if(d.liga){const s=new Set(E.ligas||[]);if(s.has(d.liga))s.delete(d.liga);else s.add(d.liga);E.ligas=[...s];guardar();pinta()}
 else if(d.sim){const s=new Set(E.sim||[]);if(s.has(d.sim))s.delete(d.sim);else s.add(d.sim);E.sim=[...s];guardar();pinta()}
 else if(d.mins){E.simMin=+d.mins;guardar();pinta()}
 else if(d.boost2){E.simB=d.boost2;guardar();pinta()}
 else if(d.solo!==undefined){soloYa=d.solo==='1';pinta()}
 else if(d.ligah){E.ligaH=+d.ligah;guardar();pinta()}
 else if(d.irObj){q='';objSec=d.irObj;objFiltro='todo';location.hash='objetos'}
 else if(d.irPer){cosQ=q;q='';perSec='catalogo';location.hash='personaje'}
 else if(d.irDin){q='';dinSec='metodos';soloYa=false;saltar={f:'m-'+d.irDin};location.hash='dinero'}
 else if(d.modo){modoCombate=d.modo;pinta(true)}
 else if(d.filtro){filtro=d.filtro;pinta()}
 else if(d.ev){const[k,s]=d.ev.split(':');E.evento[k]=Math.min(EV_MAX[k],Math.max(0,E.evento[k]+ +s));guardar();pinta()}
 else if(d.ir){const[f,i]=d.ir.split(':');q='';filtro='todo';saltar={f,l:f+'-'+i};if(vista()==='ruta')pinta();else location.hash='ruta'}
 else if(d.irRiv){q='';rivalSel=d.irRiv;location.hash='combate'}
 else if(d.tipo){const x=d.tipo,i=tiposSel.indexOf(x);if(i>=0)tiposSel.splice(i,1);else{if(tiposSel.length>=2)tiposSel.shift();tiposSel.push(x)}pinta()}
 
 else if(d.timer){E.timers[d.timer]=Date.now();guardar();pinta()}
 else if(d.fase){const f=document.getElementById(d.fase);if(f){f.open=true;f.scrollIntoView({block:'start',behavior:'smooth'})}}});
document.addEventListener('input',ev=>{const x=ev.target;if(x.id==='q'){q=x.value;document.getElementById('resultados').innerHTML=resultados()}else if(x.id==='cq'){cosQ=x.value;document.getElementById('cosres').innerHTML=resultCos()}else if(x.id==='pv'||x.id==='pc'||x.id==='tp'){const n=s=>+String(s).replace(/\D/g,'')||0;if(x.id==='pv')E.gtlV=n(x.value);if(x.id==='pc')E.gtlC=n(x.value);if(x.id==='tp')E.gtlT=x.value;guardar();document.getElementById('gtlres').innerHTML=gtlCalc()}});
addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();instalar=ev;if(vista()==='mas')pinta()});
// Mando de la consola: LB/RB cambian de sección y la cruceta desplaza. Sin animación: es uso repetido.
let mandoAntes=[],bucleMando=false;
function leeMando(){const m=[...(navigator.getGamepads?navigator.getGamepads():[])].find(Boolean);if(!m){bucleMando=false;return}const b=m.buttons.map(x=>x.pressed),i=VISTAS.findIndex(x=>x[0]===vista());if(b[5]&&!mandoAntes[5])location.hash=VISTAS[(i+1)%VISTAS.length][0];if(b[4]&&!mandoAntes[4])location.hash=VISTAS[(i-1+VISTAS.length)%VISTAS.length][0];if(b[13])scrollBy(0,18);if(b[12])scrollBy(0,-18);mandoAntes=b;requestAnimationFrame(leeMando)}
addEventListener('gamepadconnected',()=>{if(!bucleMando){bucleMando=true;requestAnimationFrame(leeMando)}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.paso){E.hechos[t.dataset.paso]=t.checked;guardar();const li=t.closest('.paso');if(li)li.classList.toggle('hecho',t.checked);setTimeout(pinta,reducido()?0:240)}else if(t.id==='f-dex'||t.id==='f-bp'||t.id==='f-h'){E.ficha=E.ficha||{};const n=parseInt(t.value.replace(/\D/g,''),10);if(!isNaN(n)){E.ficha[t.id.slice(2)]=n;guardar();pinta()}}else if(t.id==='dinero'){const n=parseInt(t.value.replace(/\D/g,''),10);if(!isNaN(n)){E.dinero=n;guardar();pinta()}}});
function editaMov(i,j){const v=E.equipo[i].mov[j],dl=document.getElementById('dlg'),f=document.getElementById('dlgf');
 f.innerHTML='<h2>'+esc(E.equipo[i].sp)+': cambiar movimiento</h2><label>Nombre<input id="mn" value="'+esc(v[0])+'" maxlength="24" required></label><label>Tipo<select id="mt">'+TT.map(t=>'<option value="'+t+'"'+(t===v[1]?' selected':'')+'>'+TN[t]+'</option>').join('')+'</select></label><label>Potencia (0 si no hace daño)<input id="mp" type="number" min="0" max="250" value="'+(+v[2]||0)+'"></label><div class="fila-acc"><button class="btn" value="ok">Guardar</button><button class="btn sec" value="no" formnovalidate>Cancelar</button></div>';
 dl.onclose=()=>{if(dl.returnValue==='ok'){const n=document.getElementById('mn').value.trim();if(n){E.equipo[i].mov[j]=[n,document.getElementById('mt').value,+document.getElementById('mp').value||0];guardar();pinta()}}};dl.showModal()}
setInterval(()=>{const el=document.getElementById('timers');if(el)el.innerHTML=timersH()},1000);

(async()=>{try{const[base,ruta,riv,din,obj,per,cos]=await Promise.all([json('partida'),json('ruta'),json('rivales'),json('dinero'),json('objetos'),json('personaje'),json('cosmeticos')]);DIN=din;OBJ=obj;PER=per;COS=cos;RUTA=ruta;RIV=riv.lista;INM=riv.inmunidades;E=fusiona(base,leerLocal());E.evento=Object.assign({gat:0,fla:20,inc:0},E.evento);pinta(true)}catch(e){document.getElementById('main').innerHTML='<div class="bloque"><h1>No se han podido cargar los datos</h1><p>Revisa la conexión y vuelve a abrir la página.</p></div>'}
 if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})})();
